// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // airDrop requires msg.sender to be a Bank-like contract returning the
        // matching token hash, so route the call through a Bank helper whose
        // address is the actor.
        Bank caller = new Bank();
        vm.assume(address(caller) != address(0));
        // drive c through airDrop via the Bank helper as the adversarial counterparty
        try this.callAirDrop(caller, c) {
            // postcondition: after a successful airDrop the caller holds exactly 20 tokens
            assertTrue(c.tokenBalance(address(caller)) == 20);
        } catch {
            // if the airdrop reverts, balance must remain zero in both versions
            assertTrue(c.tokenBalance(address(caller)) == 0);
        }
    }

    function callAirDrop(Bank caller, ModifierEntrancy target) external {
        caller.doAirDrop(target);
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return (keccak256(abi.encodePacked("Nu Token")));
    }

    function doAirDrop(ModifierEntrancy target) external {
        target.airDrop();
    }
}
